CMAKE_NATIVE_DIAGNOSTIC_BLOCK = '    foreach(\n        kernel_consumer\n        IN ITEMS\n            bootstrap_control_test\n            bootstrap_test\n            elf_spawn_fixture_test\n            elf_spawn_model_test\n            endpoint_test\n            fdt_test\n            frame_allocator_test\n            frame_ownership_test\n            ipc_model_test\n            kernel_objects_test\n            pm_test\n            scheduler_test\n            sv39_test\n            trap_route_test\n            tty_control_syscall_test\n            tty_fault_test\n            tty_interrupt_test\n            tty_test\n            vm_bootstrap_test\n            vm_core_test\n            vm_handoff_syscall_test\n    )\n        foreach(\n            kernel_directory\n            IN ITEMS\n                boot\n                diagnostic\n                endpoint\n                execution\n                grant\n                ipc\n                memory\n                objects\n                platform\n                pm\n                scheduler\n                trap\n                tty\n                vm\n                tests/boot\n                tests/endpoint\n                tests/execution\n                tests/grant\n                tests/ipc\n                tests/memory\n                tests/objects\n                tests/pm\n                tests/ramfs\n                tests/runtime\n                tests/scheduler\n                tests/spawn\n                tests/trap\n                tests/tty\n                tests/vfs\n                tests/vm\n        )\n            target_compile_options(\n                "${kernel_consumer}"\n                PRIVATE\n                    "$<$<COMPILE_LANGUAGE:C>:-fmacro-prefix-map=${CMAKE_CURRENT_SOURCE_DIR}/kernel/${kernel_directory}/=${CMAKE_CURRENT_SOURCE_DIR}/kernel/>"\n            )\n        endforeach()\n    endforeach()'

CMAKE_TARGET_DIAGNOSTIC_BLOCK = 'foreach(\n    kernel_directory\n    IN ITEMS\n        boot\n        diagnostic\n        endpoint\n        execution\n        grant\n        ipc\n        memory\n        objects\n        platform\n        pm\n        scheduler\n        trap\n        tty\n        vm\n        tests/boot\n        tests/endpoint\n        tests/execution\n        tests/grant\n        tests/ipc\n        tests/memory\n        tests/objects\n        tests/pm\n        tests/ramfs\n        tests/runtime\n        tests/scheduler\n        tests/spawn\n        tests/trap\n        tests/tty\n        tests/vfs\n        tests/vm\n)\n    target_compile_options(\n        micros\n        PRIVATE\n            "$<$<COMPILE_LANGUAGE:C>:-fmacro-prefix-map=${CMAKE_CURRENT_SOURCE_DIR}/kernel/${kernel_directory}/=kernel/>"\n    )\nendforeach()'

BASE_CMAKE_SHA256 = '730a6dd6e29ff12cf191d3040ae607026da790be7945c94a6966c24f03c42fab'


def _relative_path(path: Path) -> str:
    candidate = path if path.is_absolute() else REPOSITORY_ROOT / path
    return candidate.relative_to(REPOSITORY_ROOT).as_posix()


def _current_relative_path(logical: str) -> str:
    if logical not in KERNEL_FILE_FACTS:
        raise AssertionError(f"unknown kernel source: {logical}")
    if logical in KERNEL_PHYSICAL_OWNER_MIGRATION:
        return logical
    return KERNEL_LOGICAL_TO_PHYSICAL[logical]


def current_path(root: Path, logical: str) -> Path:
    return root / _current_relative_path(logical)


def _member_errors(root: Path, logical: str) -> tuple[str, ...]:
    physical, expected_mode, _, _ = KERNEL_FILE_FACTS[logical]
    pending = logical in KERNEL_PHYSICAL_OWNER_MIGRATION
    selected = root / (logical if pending else physical)
    alternate = root / (physical if pending else logical)
    errors = []
    try:
        selected_status = selected.lstat()
    except FileNotFoundError:
        errors.append(f"missing current owner: {selected.relative_to(root)}")
        selected_status = None
    if selected_status is not None:
        if stat.S_ISLNK(selected_status.st_mode):
            errors.append(f"linked current owner: {selected.relative_to(root)}")
        elif not stat.S_ISREG(selected_status.st_mode):
            errors.append(f"non-ordinary current owner: {selected.relative_to(root)}")
        if f"{stat.S_IMODE(selected_status.st_mode):03o}" != expected_mode[-3:]:
            errors.append(f"mode mismatch: {selected.relative_to(root)}")
        if selected_status.st_nlink != 1:
            errors.append(f"hard-linked current owner: {selected.relative_to(root)}")
    try:
        alternate.lstat()
    except FileNotFoundError:
        pass
    else:
        errors.append(f"duplicate old/new owner: {logical}")
    return tuple(errors)


def validate_current_layout(root: Path = REPOSITORY_ROOT) -> tuple[str, ...]:
    errors = []
    seen_inodes = {}
    expected = set()
    for logical in KERNEL_LOGICAL_PATHS:
        errors.extend(_member_errors(root, logical))
        selected = current_path(root, logical)
        expected.add(selected.relative_to(root).as_posix())
        try:
            status = selected.lstat()
        except FileNotFoundError:
            continue
        if stat.S_ISREG(status.st_mode) and not stat.S_ISLNK(status.st_mode):
            identity = (status.st_dev, status.st_ino)
            if identity in seen_inodes:
                errors.append(
                    f"shared inode: {seen_inodes[identity]} and "
                    f"{selected.relative_to(root).as_posix()}"
                )
            else:
                seen_inodes[identity] = selected.relative_to(root).as_posix()

    observed = {
        path.relative_to(root).as_posix()
        for path in (root / "kernel").rglob("*")
        if path.is_file() and path.suffix in (".c", ".h")
    }
    for path in sorted(expected - observed):
        errors.append(f"missing inventoried member: {path}")
    for path in sorted(observed - expected):
        errors.append(f"unexpected kernel member: {path}")
    return tuple(errors)


def _restored_kernel_bytes(root: Path, logical: str) -> bytes:
    physical, _, expected_sha256, transports = KERNEL_FILE_FACTS[logical]
    del physical
    selected = current_path(root, logical)
    raw = selected.read_bytes()
    return _restored_include_bytes(logical, raw, expected_sha256, transports)


def _restored_include_bytes(
    relative: str,
    raw: bytes,
    expected_sha256: str,
    transports,
) -> bytes:
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as error:
        raise AssertionError(f"non-UTF-8 source: {relative}") from error
    lines = text.splitlines(keepends=True)
    for line_number, target, old_line, new_line in transports:
        expected_line = (
            old_line
            if target in KERNEL_PHYSICAL_OWNER_MIGRATION
            else new_line
        )
        if line_number > len(lines) or lines[line_number - 1] != expected_line:
            raise AssertionError(
                f"private include transport mismatch: {relative}:{line_number}"
            )
        lines[line_number - 1] = old_line
    restored = "".join(lines).encode()
    if hashlib.sha256(restored).hexdigest() != expected_sha256:
        raise AssertionError(f"original source mismatch: {relative}")
    return restored


def read_logical_bytes(root: Path, logical: str) -> bytes:
    errors = _member_errors(root, logical)
    if errors:
        raise AssertionError("; ".join(errors))
    return _restored_kernel_bytes(root, logical)


def _logical_from_path(path: Path) -> Optional[str]:
    try:
        relative = _relative_path(path)
    except ValueError:
        return None
    if relative in KERNEL_FILE_FACTS:
        return relative
    return KERNEL_PHYSICAL_TO_LOGICAL.get(relative)


def _restored_external_bytes(path: Path, relative: str) -> bytes:
    _, expected_sha256, transports = EXTERNAL_SOURCE_FACTS[relative]
    return _restored_include_bytes(
        relative,
        path.read_bytes(),
        expected_sha256,
        transports,
    )


def _restored_generator_bytes(path: Path, relative: str) -> bytes:
    expected_sha256, expected_ast, transports = GENERATOR_FILE_FACTS[relative]
    restored = _restored_include_bytes(
        relative,
        path.read_bytes(),
        expected_sha256,
        transports,
    )
    payload = ast.dump(
        ast.parse(restored.decode("utf-8")),
        include_attributes=False,
    ).encode()
    if hashlib.sha256(payload).hexdigest() != expected_ast:
        raise AssertionError(f"generator AST mismatch: {relative}")
    return restored


def _source_offsets(source: str) -> list[int]:
    offsets = [0]
    for line in source.splitlines(keepends=True):
        offsets.append(offsets[-1] + len(line))
    return offsets


def _planner_assignment_spans(source: str) -> dict[str, tuple[int, int, object]]:
    offsets = _source_offsets(source)
    selected = {}
    for node in ast.parse(source).body:
        if not isinstance(node, ast.Assign) or len(node.targets) != 1:
            continue
        target = node.targets[0]
        if not isinstance(target, ast.Name) or target.id not in ORIGINAL_PLANNER_ASSIGNMENTS:
            continue
        start = offsets[node.lineno - 1] + node.col_offset
        end = offsets[node.end_lineno - 1] + node.end_col_offset
        selected[target.id] = (start, end, ast.literal_eval(node.value))
    if set(selected) != set(ORIGINAL_PLANNER_ASSIGNMENTS):
        raise AssertionError("missing validation planner layout assignments")
    return selected


def restore_validation_plan_source(source: str) -> str:
    expected = {
        "PATH_CLASSIFICATION_EQUIVALENTS": FINAL_PATH_CLASSIFICATION_EQUIVALENTS,
        "HOST_UNIT_ONLY_INPUTS": FINAL_HOST_UNIT_ONLY_INPUTS,
    }
    replacements = []
    for name, (start, end, value) in _planner_assignment_spans(source).items():
        if value == (
            ORIGINAL_PATH_CLASSIFICATION_EQUIVALENTS
            if name == "PATH_CLASSIFICATION_EQUIVALENTS"
            else ORIGINAL_HOST_UNIT_ONLY_INPUTS
        ):
            continue
        if value != expected[name]:
            raise AssertionError(f"unexpected validation planner layout data: {name}")
        replacements.append((start, end, ORIGINAL_PLANNER_ASSIGNMENTS[name]))
    for start, end, replacement in sorted(replacements, reverse=True):
        source = source[:start] + replacement + source[end:]
    payload = ast.dump(ast.parse(source), include_attributes=False).encode()
    if hashlib.sha256(payload).hexdigest() != ORIGINAL_PLANNER_AST_SHA256:
        raise AssertionError("validation planner AST did not restore")
    return source


def original_path_classification_equivalents(rows):
    rows = tuple(rows)
    if rows == ORIGINAL_PATH_CLASSIFICATION_EQUIVALENTS:
        return rows
    if rows != FINAL_PATH_CLASSIFICATION_EQUIVALENTS:
        raise AssertionError("unexpected path-classification equivalence rows")
    return ORIGINAL_PATH_CLASSIFICATION_EQUIVALENTS


def original_host_unit_only_inputs(paths):
    paths = tuple(paths)
    if paths == ORIGINAL_HOST_UNIT_ONLY_INPUTS:
        return paths
    if paths != FINAL_HOST_UNIT_ONLY_INPUTS:
        raise AssertionError("unexpected host-unit-only inputs")
    return ORIGINAL_HOST_UNIT_ONLY_INPUTS


def restore_cmake_source(source: str) -> str:
    for logical, physical in KERNEL_LOGICAL_TO_PHYSICAL.items():
        source = source.replace(physical, logical)
    for target, (old, new) in CMAKE_INCLUDE_TRANSPORTS.items():
        if source.count(new) == 1:
            source = source.replace(new, old)
        elif source.count(old) != 1:
            raise AssertionError(f"unexpected CMake include transport: {target}")
    for block in (CMAKE_NATIVE_DIAGNOSTIC_BLOCK, CMAKE_TARGET_DIAGNOSTIC_BLOCK):
        if source.count(block) == 1:
            source = source.replace(block + "\n\n", "")
        elif block in source:
            raise AssertionError("duplicate CMake diagnostic transport")
    if hashlib.sha256(source.encode()).hexdigest() != BASE_CMAKE_SHA256:
        raise AssertionError("CMake directory transport did not restore")
    return source


def read_bytes_path(path: Path) -> bytes:
    logical = _logical_from_path(path)
    if logical is not None:
        return read_logical_bytes(REPOSITORY_ROOT, logical)
    try:
        relative = _relative_path(path)
    except ValueError:
        relative = None
    if relative in EXTERNAL_SOURCE_FACTS:
        return _restored_external_bytes(path, relative)
    if relative in GENERATOR_FILE_FACTS:
        return _restored_generator_bytes(path, relative)
    if relative == "CMakeLists.txt":
        return restore_cmake_source(path.read_text(encoding="utf-8")).encode()
    if relative == "tools/validation_plan.py":
        return restore_validation_plan_source(path.read_text(encoding="utf-8")).encode()
    return path.read_bytes()


def read_path(
    path: Path,
    encoding: Optional[str] = None,
    errors: Optional[str] = None,
) -> str:
    raw = read_bytes_path(path)
    return raw.decode(encoding or "utf-8", errors or "strict")


def is_file_path(path: Path) -> bool:
    logical = _logical_from_path(path)
    selected = current_path(REPOSITORY_ROOT, logical) if logical else path
    return selected.is_file()


def exists_path(path: Path) -> bool:
    logical = _logical_from_path(path)
    selected = current_path(REPOSITORY_ROOT, logical) if logical else path
    return selected.exists()


def glob_paths(root: Path, pattern: str) -> tuple[Path, ...]:
    try:
        root.relative_to(REPOSITORY_ROOT)
        repository_root = True
    except ValueError:
        repository_root = root == REPOSITORY_ROOT
    if repository_root and (pattern == "kernel" or pattern.startswith("kernel/")):
        return tuple(
            root / logical
            for logical in KERNEL_LOGICAL_PATHS
            if fnmatch.fnmatchcase(logical, pattern)
            and current_path(root, logical).is_file()
        )
    return tuple(root.glob(pattern))


class _RestoreGateAdapter(ast.NodeTransformer):
    _METHODS = {
        "read_path": "read_text",
        "read_bytes_path": "read_bytes",
        "is_file_path": "is_file",
        "exists_path": "exists",
    }

    def visit_Call(self, node: ast.Call) -> ast.AST:
        self.generic_visit(node)
        function = node.func
        if not (
            isinstance(function, ast.Attribute)
            and isinstance(function.value, ast.Name)
            and function.value.id == "kernel_layout_source"
        ):
            return node
        if function.attr in self._METHODS:
            if not node.args:
                raise AssertionError(f"missing adapter path: {function.attr}")
            return ast.Call(
                func=ast.Attribute(
                    value=node.args[0],
                    attr=self._METHODS[function.attr],
                    ctx=ast.Load(),
                ),
                args=node.args[1:],
                keywords=node.keywords,
            )
        if function.attr == "glob_paths":
            if len(node.args) != 2 or node.keywords:
                raise AssertionError("invalid glob adapter")
            return ast.Call(
                func=ast.Attribute(
                    value=node.args[0],
                    attr="glob",
                    ctx=ast.Load(),
                ),
                args=[node.args[1]],
                keywords=[],
            )
        if function.attr in {
            "original_host_unit_only_inputs",
            "original_path_classification_equivalents",
        }:
            if len(node.args) != 1 or node.keywords:
                raise AssertionError(f"invalid planner projection: {function.attr}")
            return node.args[0]
        return node


def _restore_gate_ast(tree: ast.Module) -> ast.Module:
    tree.body = [
        statement
        for statement in tree.body
        if not (
            isinstance(statement, ast.ImportFrom)
            and statement.module == "tests.host"
            and len(statement.names) == 1
            and statement.names[0].name == "kernel_layout_source"
        )
    ]
    restored = _RestoreGateAdapter().visit(tree)
    ast.fix_missing_locations(restored)
    return restored


def restored_gate_ast_sha256(root: Path, relative: str) -> str:
    source = (root / relative).read_text(encoding="utf-8")
    tree = _restore_gate_ast(ast.parse(source))
    payload = ast.dump(tree, include_attributes=False).encode()
    return hashlib.sha256(payload).hexdigest()
